const s=n=>{const o=n.find(".best-advanced-accordion"),t=o.find(".best-accordion-item");t.each(function(){const e=jQuery(this),i=e.find(".best-accordion-header"),c=e.find(".best-accordion-content");i.on("click",d=>{d.preventDefault(),e.hasClass("is-active")?(e.removeClass("is-active"),c.slideUp(250)):(t.removeClass("is-active"),o.find(".best-accordion-content").slideUp(250),e.addClass("is-active"),c.slideDown(250))})})};jQuery(window).on("elementor/frontend/init",()=>{elementorFrontend.hooks.addAction("frontend/element_ready/best_addons_advanced_accordion.default",n=>{s(n)})});
